<?php
if(!defined('ABSPATH')){exit;}
final class AICS_Internal_Link_Candidate_Service{
	public function discover(array $article,int $limit=50):array{$limit=max(1,min(100,$limit));$types=array('post','page');if(post_type_exists('product')&&is_post_type_viewable('product')){$types[]='product';}$existing=$this->existing_urls((string)$article['content']);$q=new WP_Query(array('post_type'=>$types,'post_status'=>'publish','has_password'=>false,'posts_per_page'=>$limit,'post__not_in'=>array_filter(array(absint($article['wordpress_post_id']??0))),'no_found_rows'=>true,'orderby'=>'date','order'=>'DESC','fields'=>'ids'));$out=array();$seen=array();foreach($q->posts as $id){$post=get_post($id);$type=$post?get_post_type_object($post->post_type):null;if(!$post||!$type||!$type->public){continue;}$url=get_permalink($id);$canonical=is_string($url)?untrailingslashit(esc_url_raw($url)):'';if(''===$canonical||isset($seen[$canonical])||isset($existing[$canonical])){continue;}$terms=wp_get_post_terms($id,array('category','post_tag'),array('fields'=>'names'));$out[]=array('candidate_id'=>'internal_'.absint($id),'post_id'=>absint($id),'post_type'=>$post->post_type,'title'=>substr(sanitize_text_field($post->post_title),0,250),'slug'=>substr(sanitize_title($post->post_name),0,200),'excerpt'=>substr(sanitize_textarea_field($post->post_excerpt),0,500),'terms'=>is_wp_error($terms)?array():array_slice(array_map('sanitize_text_field',$terms),0,20),'url'=>$canonical);$seen[$canonical]=true;}return $out;}
	private function existing_urls(string $html):array{$out=array();if(preg_match_all('/<a\s[^>]*href=["\']([^"\']+)["\']/i',$html,$m)){foreach($m[1] as $url){$absolute=wp_make_link_relative($url)===$url?home_url($url):$url;$out[untrailingslashit(esc_url_raw($absolute))]=true;}}return $out;}
}
